package com.aoo.bcg.common.concurrency;import org.junit.jupiter.api.Test;import java.time.*;import java.util.*;import java.util.concurrent.atomic.AtomicInteger;import static org.junit.jupiter.api.Assertions.*;
class ConcurrencyStallMonitorTest{@Test void reportsLongLockAndStagnantQueueWithDumpAndJfrTrigger(){var alerts=new ArrayList<ConcurrencyStallMonitor.Alert>();var jfr=new AtomicInteger();var now=Instant.parse("2026-08-23T00:00:00Z");try(var monitor=new ConcurrencyStallMonitor(()->List.of(new ConcurrencyStallMonitor.Probe("room",4,now.minusSeconds(20),Map.of("room:1",Duration.ofSeconds(20)))),Duration.ofSeconds(5),Duration.ofSeconds(10),alerts::add,jfr::incrementAndGet)){monitor.sample(now);}assertEquals(Set.of("long-lock","queue-stagnation"),alerts.stream().map(ConcurrencyStallMonitor.Alert::kind).collect(java.util.stream.Collectors.toSet()));assertTrue(alerts.stream().allMatch(a->!a.threadDump().isBlank()));assertEquals(2,jfr.get());}}
